/* HIA Theme Builder 生成 — {{meta:name}}（Obsidian 主题）
   Generated by HIA Theme Builder — target: Obsidian CSS theme.
   前置：Obsidian 1.0+；放入 .obsidian/snippets/ 并在设置 → 外观 → CSS 代码片段中启用。 */

/* ===== Obsidian 基础变量（@settings 兼容口径）===== */
body {
  --hia-primary: {{token:primary.500}};
  --hia-primary-deep: {{token:primary.900}};
  --hia-primary-soft: {{token:primary.50}};
  --hia-secondary: {{token:secondary.500}};
  --hia-on-primary: {{token:on:primary}};
  --hia-text: {{token:primary.900}};
  --hia-font-body: {{token:font:body}};
}

/* ===== 主题基色 ===== */
.theme-dark {
  --background-primary: {{token:primary.950}};
  --background-secondary: {{token:primary.1000}};
  --text-normal: {{token:primary.100}};
}
.theme-light {
  --background-primary: #ffffff;
  --background-secondary: {{token:primary.50}};
  --text-normal: {{token:primary.900}};
}

/* ===== 工作台 ===== */
.workspace-ribbon { background: var(--hia-primary-soft); }
.workspace-leaf-header { background: var(--hia-primary-soft); }
.status-bar { background: var(--hia-primary-soft); color: var(--hia-text); }

/* ===== 编辑/阅读视图 ===== */
.markdown-preview-view, .markdown-source-view { font-family: var(--hia-font-body); }
.markdown-preview-view h1, .markdown-source-view h1 { color: var(--hia-primary-deep); }
.markdown-preview-view h2, .markdown-source-view h2 { color: var(--hia-primary-deep); }
.markdown-preview-view.markdown-rendered { background: var(--background-primary); }

/* ===== 代码块 ===== */
.markdown-preview-view pre, .markdown-source-view pre {
  background: var(--hia-primary-soft);
  border-radius: 8px;
}
.markdown-preview-view code { color: var(--hia-secondary); }

/* ===== 引用块 ===== */
.markdown-preview-view blockquote, .markdown-preview-view.callout {
  border-left: 3px solid var(--hia-primary);
  background: var(--hia-primary-soft);
}

/* ===== 侧栏文件列表 ===== */
.nav-files-container { background: var(--background-secondary); }
.nav-file-title, .nav-folder-title { color: var(--hia-text); }
.nav-file-title.is-active, .nav-folder-title.is-active { background: var(--hia-primary-soft); }
